// The stock photos the prompts allow the model to use (generated by scripts/make_stock.py).
export const STOCK = {
  landscape: [0, 1, 2, 3, 4, 5].map((i) => `/stock/landscape${i}.jpg`),
  portrait: [0, 1, 2, 3].map((i) => `/stock/portrait${i}.jpg`),
  square: [0, 1, 2, 3].map((i) => `/stock/square${i}.jpg`),
};
export const ALL_STOCK = [...STOCK.landscape, ...STOCK.portrait, ...STOCK.square];
export const STOCK_NAMES = ALL_STOCK.map((p) => p.replace("/stock/", ""));
